with valid as (select *, concat(location, ' ', dept_name) as location_dept_name from departments where location is not null) select id, dept_name, budget, lead(budget) over (partition by location order by budget, id) as next_budget, lag(budget) over (partition by location order by budget, id) as prev_budget, row_number() over (partition by location order by budget, id) as row_seq, rank() over (partition by location order by budget desc nulls first) as budget_rank from valid
